export function evaluate({ inputs, time }) {
  const u = Number(inputs.launchSpeed ?? 4);
  const g = Number(inputs.gravity ?? 9.8);
  const tTop = u / g;
  const hTop = (u * u) / (2 * g);

  const t = Math.max(0, time);

  let yToss = u * t - 0.5 * g * t * t;
  let vToss = u - g * t;
  let aToss = -g;

  let yDrop = hTop;
  let vDrop = 0;
  let aDrop = 0;
  let gateOpen = false;

  if (t >= tTop) {
    gateOpen = true;
    const dt = t - tTop;
    yDrop = hTop - 0.5 * g * dt * dt;
    vDrop = -g * dt;
    aDrop = -g;
  }

  const y0 = 340;
  const heightScale = 120;
  const pYToss = y0 - yToss * heightScale;
  const pYDrop = y0 - yDrop * heightScale;
  const pYTop = y0 - hTop * heightScale;

  const tossX = 160;
  const dropX = 480;

  let tossState = "At launch";
  if (Math.abs(t - tTop) < 0.01) tossState = "At the top";
  else if (t < tTop) tossState = "Rising";
  else if (yToss <= 0.01) tossState = "At launch height";
  else tossState = "Falling";

  let dropState = "Held in place";
  if (t >= tTop) {
    if (Math.abs(t - tTop) < 0.01) dropState = "Just released";
    else if (yDrop <= 0.01) dropState = "At launch height";
    else dropState = "Falling together";
  }

  const objects = [];

  const panelToss = sdk.panel({
    id: "lane.toss",
    x: 20,
    y: 30,
    w: 280,
    h: 360,
    title: "Toss Lane",
    state: tossState
  });
  objects.push(...panelToss);

  const panelDrop = sdk.panel({
    id: "lane.drop",
    x: 340,
    y: 30,
    w: 280,
    h: 360,
    title: "Drop Lane",
    state: dropState
  });
  objects.push(...panelDrop);

  objects.push(sdk.axis("axis.toss", {
    x: 50,
    y: y0,
    length: 260,
    orientation: "y",
    min: 0,
    max: 2.2,
    ticks: [0, 0.5, 1.0, 1.5, 2.0],
    label: "Height",
    unit: "m"
  }));

  objects.push(sdk.axis("axis.drop", {
    x: 370,
    y: y0,
    length: 260,
    orientation: "y",
    min: 0,
    max: 2.2,
    ticks: [0, 0.5, 1.0, 1.5, 2.0],
    label: "Height",
    unit: "m"
  }));

  objects.push(sdk.line("ref.ground.toss", 40, y0, 280, y0, { role: "neutral", opacity: 0.3 }));
  objects.push(sdk.line("ref.ground.drop", 360, y0, 600, y0, { role: "neutral", opacity: 0.3 }));

  objects.push(sdk.line("ref.apex.toss", 40, pYTop, 280, pYTop, { role: "neutral", opacity: 0.4 }));
  objects.push(sdk.line("ref.apex.drop", 360, pYTop, 600, pYTop, { role: "neutral", opacity: 0.4 }));

  objects.push(...sdk.gate("gate", dropX, pYTop, { open: gateOpen, w: 40, label: "Release" }));

  if (gateOpen) {
    objects.push(sdk.circle("ghost.top.toss", tossX, pYTop, 24, { opacity: 0.3, role: "neutral" }));
    objects.push(sdk.circle("ghost.top.drop", dropX, pYTop, 24, { opacity: 0.3, role: "neutral" }));
  }

  objects.push(sdk.circle("ball.toss", tossX, pYToss, 24, { role: "learner" }));
  objects.push(sdk.circle("ball.drop", dropX, pYDrop, 24, { role: "observed" }));

  const vScale = 15;
  const aScale = 5;

  objects.push(...sdk.vector("vec.v.toss", { x: tossX - 18, y: pYToss }, {
    value: vToss,
    direction: "up",
    scale: vScale,
    label: "v",
    role: "learner"
  }));

  objects.push(...sdk.vector("vec.a.toss", { x: tossX + 18, y: pYToss }, {
    value: aToss,
    direction: "up",
    scale: aScale,
    label: "a",
    role: "warning"
  }));

  objects.push(...sdk.vector("vec.v.drop", { x: dropX - 18, y: pYDrop }, {
    value: vDrop,
    direction: "up",
    scale: vScale,
    label: "v",
    role: "observed"
  }));

  objects.push(...sdk.vector("vec.a.drop", { x: dropX + 18, y: pYDrop }, {
    value: aDrop,
    direction: "up",
    scale: aScale,
    label: "a",
    role: "warning"
  }));

  const calloutTossLines = [
    `v: ${sdk.format(vToss, 2)} m/s`,
    `a: ${sdk.format(aToss, 2)} m/s²`
  ];
  objects.push(...sdk.callout(tossX + 45, pYToss - 20, calloutTossLines, { id: "callout.toss", role: "learner" }));

  const calloutDropLines = [
    `v: ${sdk.format(vDrop, 2)} m/s`,
    `a: ${sdk.format(aDrop, 2)} m/s²`
  ];
  objects.push(...sdk.callout(dropX + 45, pYDrop - 20, calloutDropLines, { id: "callout.drop", role: "observed" }));

  return {
    frame: sdk.frame(objects, { width: 640, height: 420 }),
    quantities: {
      launchSpeed: u,
      gravity: g,
      apexTime: tTop,
      apexHeight: hTop,
      tossedVelocity: vToss,
      tossedAcceleration: aToss,
      tossedHeight: yToss,
      dropVelocity: vDrop,
      dropAcceleration: aDrop,
      dropHeight: yDrop
    }
  };
}
